  'Name in Badini': 'الاسم بالكردية البادينية',
  'From Wikipedia, Wikidata and Wikimedia Commons (and the model’s web search, when the route allows it). They can be wrong or out of date: check each fact, and switch off any you are not sure of. Changes are used when the storyboard is planned again (Details → Plan the storyboard again).':
    'من ويكيبيديا وويكي بيانات وويكيميديا كومنز (ومن بحث النموذج على الويب حين يسمح المسار بذلك). قد تكون خاطئة أو قديمة: تحقّق من كل حقيقة، وأوقف أي حقيقة لست متأكداً منها. تُستخدم التغييرات عند تخطيط لوحة المشاهد من جديد (التفاصيل ← خطّط لوحة المشاهد من جديد).',
  'Look up an organisation, a place or a person: real facts, photographs and a logo from Wikipedia, Wikidata and Wikimedia Commons.':
    'ابحث عن مؤسسة أو مكان أو شخص: حقائق حقيقية وصور وشعار من ويكيبيديا وويكي بيانات وويكيميديا كومنز.',
  'No free logo was found — a Wikipedia’s own logo is usually “fair use”, which a video may not reuse. Add yours under Look → Brand.':
    'لم يُعثر على شعار حر — شعار ويكيبيديا نفسه غالباً «استعمال عادل» لا يجوز إعادة استخدامه في فيديو. أضف شعارك من المظهر ← العلامة التجارية.',
  'No reusable pictures of it were found. The scenes get openly licensed stock pictures instead.':
    'لم يُعثر على صور له يجوز إعادة استخدامها. ستحصل المشاهد بدلاً منها على صور عامة مرخّصة ترخيصاً مفتوحاً.',
  'Nothing was found for “{name}”. Try its full name, in English.':
    'لم يُعثر على شيء عن «{name}». جرّب اسمه الكامل بالإنجليزية.',
  'These go into the scenes that take a picture before any stock search. Openly licensed (CC0, public domain, CC BY or CC BY-SA) and credited at the end.':
    'توضع هذه في المشاهد التي تحمل صورة قبل أي بحث عن صور عامة. مرخّصة ترخيصاً مفتوحاً (CC0 أو ملكية عامة أو CC BY أو CC BY-SA) ويُذكر أصحابها في النهاية.',
  'What is found is used when the storyboard is planned again (Details → Plan the storyboard again).':
    'يُستخدم ما يُعثر عليه عند تخطيط لوحة المشاهد من جديد (التفاصيل ← خطّط لوحة المشاهد من جديد).',
  'Listen': 'استمع',
  'Openverse is asking for a pause. Try again in a minute.': 'يطلب Openverse مهلة قصيرة. حاول مرة أخرى بعد دقيقة.',
  'Openverse could not be reached. Check the connection and try again.': 'تعذّر الوصول إلى Openverse. تحقّق من الاتصال وحاول مرة أخرى.',
  'That track is too big to keep in the video. Choose a shorter one.': 'هذا المقطع أكبر من أن يُحفظ في الفيديو. اختر مقطعًا أقصر.',
  'That track could not be read as MP3. Choose another.': 'تعذّرت قراءة هذا المقطع بصيغة MP3. اختر غيره.',
  'It took too long to answer. Try again.': 'استغرق الرد وقتًا طويلًا. حاول مرة أخرى.',
  'Captions': 'الترجمة النصية',
  'The narration on screen, a few words at a time as they are said': 'نص التعليق الصوتي على الشاشة، بضع كلمات في كل مرة مع نطقها',
  'Captions show the narration, so they appear once narration is on.': 'الترجمة النصية تعرض التعليق الصوتي، لذا تظهر عند تشغيل التعليق الصوتي.',
  'Burned into the video in its own typeface, above where phone apps put their buttons — for the many who watch with the sound off.': 'تُطبع داخل الفيديو بخطّه، فوق المكان الذي تضع فيه تطبيقات الهاتف أزرارها — للكثيرين الذين يشاهدون بلا صوت.',
  'fetch the music': 'جلب الموسيقى',
  'Music': 'الموسيقى',
  'Openly licensed music under the whole video': 'موسيقى بترخيص مفتوح على امتداد الفيديو',
  'Music volume': 'مستوى صوت الموسيقى',
  'Shorter than the video, so it loops, the joins blended, to fill {n} seconds. It fades in at the start and out at the end.': 'أقصر من الفيديو، لذا تتكرر بوصلات ممزوجة لتملأ {n} ثانية. تتصاعد تدريجيًا في البداية وتخفت في النهاية.',
  'It fades in at the start and out at the end.': 'تتصاعد تدريجيًا في البداية وتخفت في النهاية.',
  'Under the voice it drops to about a third, and comes back between lines.': 'وتحت الصوت تنخفض إلى نحو الثلث، ثم تعود بين الجمل.',
  'Mood': 'الطابع',
  'Describe the music': 'صف الموسيقى',
  'Or describe it, in English: soft guitar, happy ukulele…': 'أو صفها بالإنجليزية: soft guitar، happy ukulele…',
  'Looking for music…': 'جارٍ البحث عن موسيقى…',
  'find music': 'البحث عن موسيقى',
  'Nothing usable came back for that. Try other words or another mood.': 'لم يأتِ شيء صالح للاستخدام. جرّب كلمات أخرى أو طابعًا آخر.',
  'Music found': 'الموسيقى التي وُجدت',
  'Use': 'استخدام',
  'From Openverse — Freesound, Jamendo and Wikimedia Commons — only under licences that allow reuse (CC0, public domain, CC BY, CC BY-SA). Its credit goes at the end with the pictures’.': 'من Openverse — Freesound وJamendo وويكيميديا كومنز — وفقط بتراخيص تسمح بإعادة الاستخدام (CC0، الملكية العامة، CC BY، CC BY-SA). يُذكر مصدرها في النهاية مع مصادر الصور.',
  'Made longer to fit the voice: {list}.': 'أُطيلت لتتسع للصوت: {list}.',
  'scene {n} ({from} → {to} s)': 'المشهد {n} ({from} ← {to} ث)',
  'Still too long for its scene even at 20 seconds: {list}. Shorten those lines.': 'ما زالت أطول من مشهدها حتى عند 20 ثانية: {list}. اختصر هذه الجمل.',
  'scene {n}': 'المشهد {n}',
  'The answer could not be read as narration. Try again.': 'تعذّرت قراءة الرد كتعليق صوتي. حاول مرة أخرى.',
  '{n} lines written. Read them, change what you like, then make the voice.': 'كُتبت {n} جمل. اقرأها وعدّل ما تشاء، ثم اصنع الصوت.',
  'write the narration': 'كتابة التعليق الصوتي',
  '{n} lines spoken. Each fits its scene.': 'نُطقت {n} جمل، وكلٌّ منها يتسع في مشهده.',
