  'Narration': 'التعليق الصوتي',
  'A voice reads a line in every scene': 'صوت يقرأ جملة في كل مشهد',
  'Voice': 'الصوت',
  'Spoken by {name} with {model}. The key goes only to {host}.': 'بصوت {name} عبر {model}. يُرسَل المفتاح إلى {host} فقط.',
  'No provider here can make a voice. Add an OpenAI-compatible provider with its key in Settings. Until then, ▶ reads a line in this computer’s own voice — a preview only, which cannot go into the video.': 'لا يوجد هنا مزوّد يستطيع صنع صوت. أضف في الإعدادات مزوّدًا متوافقًا مع OpenAI مع مفتاحه. وحتى ذلك الحين يقرأ ▶ الجملة بصوت هذا الحاسوب — للمعاينة فقط، ولا يمكن وضعه في الفيديو.',
  'No speech service has a Kurdish voice yet. The voice reads the Kurdish letters as well as it can, so listen before you export.': 'لا توجد بعدُ خدمة نطق بصوت كردي. يقرأ الصوت الحروف الكردية قدر استطاعته، فاستمع قبل التصدير.',
  'Writing the narration needs the video’s model, which this window was not given.': 'كتابة التعليق الصوتي تحتاج إلى نموذج الفيديو، ولم يُعطَ لهذه النافذة.',
