  'Change any word above, then make it — or see a sample first.': 'غيّر أي كلمة في الأعلى ثم اصنعه — أو شاهد عيّنة أولاً.',
  'Open a sample storyboard': 'افتح لوحة مشاهد نموذجية',
  'Placeholder words, ready to preview and edit. No model is asked.': 'كلمات مؤقتة جاهزة للمعاينة والتعديل. لا يُسأل أي نموذج.',
  'A sample from “{name}”': 'عيّنة من «{name}»',
  'Placeholder words that show the shape of the video — no model has written anything yet. Change every line, or have the model plan it from your request.': 'كلمات مؤقتة تُظهر شكل الفيديو — لم يكتب أي نموذج شيئاً بعد. غيّر كل سطر، أو دع النموذج يخطّط له من طلبك.',
  'Plan it with the model': 'خطّط له بالنموذج',
  'The words are a template’s placeholders. Replace every one — and check every name, number and claim — before you publish it.': 'النصوص كلمات مؤقتة من قالب. استبدلها كلها — وتحقّق من كل اسم ورقم وادّعاء — قبل أن تنشره.',
