  'Skipped the rest: at most {n} changes a message': 'ئەوانی تر پەڕێنران: لە هەر نامەیەکدا زۆرترین {n} گۆڕانکاری',
  'Skipped: a video holds at most {n} scenes': 'پەڕێنرا: ڤیدیۆ زۆرترین {n} دیمەن لەخۆ دەگرێت',
