  'Add an API key in Settings to talk to the video.': 'بۆ قسەکردن لەگەڵ ڤیدیۆکە، کلیلی API لە ڕێکخستنەکاندا زیاد بکە.',
  'Wait until the storyboard and its pictures are finished.': 'چاوەڕێ بکە تا نەخشەی دیمەنەکان و وێنەکانی تەواو دەبن.',
