  'Say what to change in your own words — shorter scenes, a new style, calmer music, a translation. The model changes the storyboard and lists every change under its answer; one undo takes a whole message back.': 'بە وشەی خۆت بڵێ چی بگۆڕدرێت — دیمەنی کورتتر، ستایلێکی نوێ، مۆسیقای ئارامتر، وەرگێڕان. مۆدێلەکە نەخشەی دیمەنەکان دەگۆڕێت و هەموو گۆڕانکارییەک لە ژێر وەڵامەکەیدا دەنووسێت؛ یەک گەڕانەوە هەموو نامەیەک هەڵدەوەشێنێتەوە.',
  'The answer could not be read, so nothing was changed. Try again, or ask for less at once.': 'وەڵامەکە نەخوێندرایەوە، بۆیە هیچ شتێک نەگۆڕدرا. دووبارە هەوڵبدەرەوە، یان کەمتر بە یەکجار داوا بکە.',
