  'This address cannot be made into a QR code. Write it like uod.ac or https://uod.ac/apply.': 'ناتوانرێت ئەم ناونیشانە بکرێت بە کۆدی QR. وەک uod.ac یان https://uod.ac/apply بینووسە.',
