  'Look the subject up on the web first': 'سەرەتا بابەتەکە لە وێب بگەڕێ',
  'Real facts, photographs and the logo from Wikipedia, Wikidata and Wikimedia Commons, given to the model before it plans. You see and check every one under “Found on the web”.':
    'ڕاستیی ڕاستەقینە، وێنە و لۆگۆ لە ویکیپیدیا، ویکیداتا و ویکیمیدیا کۆمنزەوە، پێش ئەوەی مۆدێلەکە پلان دابنێت پێی دەدرێن. هەموویان لە «لە وێب» دەبینیت و دەیانپشکنیت.',
