  'Year in review': 'کورتەی ساڵ',
  'Thank-you or greeting': 'سوپاس یان پیرۆزبایی',
  'Your campus, your colleges, and how to apply.': 'کەمپەس و کۆلێژەکانت، و چۆنیەتی خۆتۆمارکردن.',
  'What is new, why it matters, and where to get it.': 'چی نوێیە، بۆچی گرنگە، و لە کوێ دەست دەکەوێت.',
  'An invitation, with the date, the place and how to reply.': 'بانگهێشتێک، لەگەڵ بەروار و شوێن و چۆنیەتی وەڵامدانەوە.',
  'Your care, your services, and how to book.': 'چاودێری و خزمەتگوزارییەکانت، و چۆنیەتی کات دیاریکردن.',
  'Your dishes, the atmosphere, and how to order.': 'خواردنەکانت، کەشەکە، و چۆنیەتی داواکردن.',
