  'In use': 'بەکاردێت',
  'Use the logo’s colours': 'ڕەنگەکانی لۆگۆ بەکاربهێنە',
  'Start from a template': 'لە قاڵبێکەوە دەست پێ بکە',
  'Change any word above, then make it — or see a sample first.': 'هەر وشەیەکی سەرەوە بگۆڕە، پاشان دروستی بکە — یان سەرەتا نموونەیەک ببینە.',
  'Open a sample storyboard': 'نەخشەی دیمەنی نموونە بکەرەوە',
  'Placeholder words, ready to preview and edit. No model is asked.': 'وشەی کاتی، ئامادە بۆ پێشبینین و دەستکاری. پرسیار لە هیچ مۆدێلێک ناکرێت.',
  'A sample from “{name}”': 'نموونەیەک لە «{name}»',
  'Placeholder words that show the shape of the video — no model has written anything yet. Change every line, or have the model plan it from your request.': 'وشەی کاتی کە شێوەی ڤیدیۆکە نیشان دەدەن — هێشتا هیچ مۆدێلێک هیچی نەنووسیوە. هەموو دێڕێک بگۆڕە، یان با مۆدێلەکە لە داواکارییەکەتەوە پلانی بۆ دابنێت.',
  'Plan it with the model': 'بە مۆدێلەکە پلانی بۆ دابنێ',
  'The words are a template’s placeholders. Replace every one — and check every name, number and claim — before you publish it.': 'وشەکان وشەی کاتیی قاڵبێکن. هەموویان بگۆڕە — و هەموو ناو و ژمارە و بانگەشەیەک بپشکنە — پێش بڵاوکردنەوە.',
  'Download MP4': 'داگرتنی MP4',
  'Download MP4 at {quality}': 'داگرتنی MP4 بە {quality}',
  'Renders the video on this computer and saves it in your Downloads folder.': 'ڤیدیۆکە لەسەر ئەم کۆمپیوتەرە دروست دەکات و لە بوخچەی داگرتنەکانت پاشەکەوتی دەکات.',
  'More ways to save': 'ڕێگای تری پاشەکەوتکردن',
  'with sound': 'لەگەڵ دەنگ',
  'Into your Downloads folder, never over a file that is there.': 'بۆ بوخچەی داگرتنەکانت، بێ ئەوەی جێی هیچ فایلێکی ناوی بگرێتەوە.',
  'Resolution': 'ڕوونی',
  'What YouTube asks for in a thumbnail, and plenty for a phone.': 'ئەوەی YouTube بۆ وێنۆچکە داوای دەکات، و بۆ مۆبایل تەواو بەسە.',
  'Four times the pixels of Full HD: sharpest on a large screen, and a longer wait.': 'چوار هێندەی پیکسڵەکانی Full HD: ڕوونترین لەسەر شاشەی گەورە، و چاوەڕوانیی درێژتر.',
